        GetGraph()->GetEventWriter().EventCleanup(phi->GetId(), phi->GetPc());
        anyPhiRemoved = true;
    }

    if (anyPhiRemoved) {
        RemovalPhi(bb, newEmptyBlocks);
    }
}

