enum class CleanupMode : uint8_t {
    SKIP,
    LIGHT,
    FULL,
};

CleanupMode GetCleanupMode(compiler::Cleanup::Requirement requirement, bool forceFull, bool previousPassChanged)
{
    if (forceFull) {
        return CleanupMode::FULL;
    }
    switch (requirement) {
        case compiler::Cleanup::Requirement::NONE:
            return previousPassChanged ? CleanupMode::LIGHT : CleanupMode::SKIP;
        case compiler::Cleanup::Requirement::LIGHT:
            return CleanupMode::LIGHT;
        case compiler::Cleanup::Requirement::FULL:
            return CleanupMode::FULL;
        default:
            UNREACHABLE();
    }
}

bool RunCleanupMode(compiler::Graph *graph, CleanupMode barrier)
{
    switch (barrier) {
        case CleanupMode::SKIP:
            return false;
        case CleanupMode::LIGHT:
            return graph->RunPass<compiler::Cleanup>();
        case CleanupMode::FULL:
            return graph->RunPass<compiler::Cleanup>(false);
        default:
            UNREACHABLE();
    }
}

template <typename T>
constexpr bool REQUIRES_FULL_CLEANUP_BEFORE = std::is_same_v<T, compiler::Lowering>;

template <typename First, typename Second, typename... Rest>
bool RunOpts(compiler::Graph *graph, bool previousPassChanged, BytecodeOptIrInterface *iface = nullptr);

template <typename Last>
bool RunOpts(compiler::Graph *graph, bool previousPassChanged, BytecodeOptIrInterface *iface = nullptr);

template <typename T>
bool RunPassWithIface(compiler::Graph *graph, [[maybe_unused]] BytecodeOptIrInterface *iface)
{
#ifndef NDEBUG
    // NOLINTNEXTLINE(readability-braces-around-statements, bugprone-suspicious-semicolon)
    if constexpr (std::is_same_v<T, compiler::Lowering>) {
        graph->SetLowLevelInstructionsEnabled();
    }
#endif  // NDEBUG
    if constexpr (std::is_same_v<T, ConstArrayResolver>) {
        return graph->RunPass<ConstArrayResolver>(iface);
    } else if constexpr (std::is_same_v<T, compiler::SimplifyStringBuilder>) {
        if (NeedToRunSimplifyStringBuilder(graph->GetLanguage())) {
            return graph->RunPass<compiler::SimplifyStringBuilder>();
        }
        return false;
    } else {
        return graph->RunPass<T>();
    }
}

template <typename T>
bool RunOpt(compiler::Graph *graph, bool previousPassChanged, [[maybe_unused]] BytecodeOptIrInterface *iface)
{
    if (previousPassChanged || REQUIRES_FULL_CLEANUP_BEFORE<T>) {
        auto requirement = compiler::Cleanup::GetRequirement(graph);
        auto mode = GetCleanupMode(requirement, REQUIRES_FULL_CLEANUP_BEFORE<T>, previousPassChanged);
        RunCleanupMode(graph, mode);
    }
    return RunPassWithIface<T>(graph, iface);
}

template <typename First, typename Second, typename... Rest>
bool RunOpts(compiler::Graph *graph, bool previousPassChanged, BytecodeOptIrInterface *iface)
{
    bool changed = RunOpt<First>(graph, previousPassChanged, iface);
    return RunOpts<Second, Rest...>(graph, changed, iface);
}

template <typename Last>
bool RunOpts(compiler::Graph *graph, bool previousPassChanged, BytecodeOptIrInterface *iface)
{
    return RunOpt<Last>(graph, previousPassChanged, iface);
}

